const lookup=new Map(Object.entries(groups).flatMap(([country,ids])=>ids.split(' ').map(id=>[id,country])));
const names=new Intl.DisplayNames(['en'],{type:'region'});
export const flagCountries=Object.keys(groups).map(code=>code.toLowerCase());
export function airportFlag(id){
 const country=lookup.get(String(id).toUpperCase());
 return country?{country,name:names.of(country),src:flagAssets[country]}:null;
}
